(() => {
  'use strict';
  const SAVE_KEY = 'nullspace-lingua-save-v1';
  const nodes = {
    home:{name:'The Quiet Boot',title:'HOME DIRECTORY',type:'LOCAL PROCESS',coord:'0x0001 · LOOPBACK',glyph:'⌘',index:'SECTOR 00 / 08',desc:'A blank prompt blinks in the dark. Somewhere beyond this machine, the network is dreaming.',tags:['LOCAL','STABLE','UNEXPLORED'],neighbors:['relay','archive'],pos:[50,52]},
    relay:{name:'Relay Garden',title:'RELAY GARDEN',type:'SIGNAL EXCHANGE',coord:'0x01A4 · 12 HOPS',glyph:'⌁',index:'SECTOR 01 / 08',desc:'Packets drift like pollen through a garden of sleeping connections. A signal repeats your name.',tags:['SIGNAL','OPEN PORT','UNEXPLORED'],neighbors:['home','mirror','void'],pos:[26,36]},
    archive:{name:'The Long Archive',title:'LONG ARCHIVE',type:'MEMORY BANK',coord:'0x02F0 · 08 HOPS',glyph:'▤',index:'SECTOR 02 / 08',desc:'Endless shelves of thoughts no one remembers writing. One file glows beneath the dust.',tags:['READ ONLY','DEEP STORAGE','UNEXPLORED'],neighbors:['home','cache'],pos:[25,72]},
    mirror:{name:'Mirror Protocol',title:'MIRROR PROTOCOL',type:'RECURSIVE INSTANCE',coord:'0x04C2 · 19 HOPS',glyph:'◈',index:'SECTOR 03 / 08',desc:'A second cursor follows yours, half a beat behind. It seems to know what you will type.',tags:['RECURSIVE','UNSTABLE','UNEXPLORED'],neighbors:['relay','kernel'],pos:[51,20]},
    cache:{name:'Cache Cathedral',title:'CACHE CATHEDRAL',type:'VOLATILE MEMORY',coord:'0x05D9 · 22 HOPS',glyph:'▦',index:'SECTOR 04 / 08',desc:'A vast cache hums with abandoned images. Their colors persist, even after their owners are gone.',tags:['VOLATILE','FRAGMENTED','UNEXPLORED'],neighbors:['archive','kernel'],pos:[51,84]},
    void:{name:'The Unwritten',title:'THE UNWRITTEN',type:'UNALLOCATED SPACE',coord:'0x07FF · 31 HOPS',glyph:'∅',index:'SECTOR 05 / 08',desc:'Nothing has been written here. Yet the silence has the shape of something waiting to be named.',tags:['UNKNOWN','NO INDEX','UNEXPLORED'],neighbors:['relay','kernel'],pos:[76,36]},
    kernel:{name:'Kernel of Dawn',title:'KERNEL OF DAWN',type:'ROOT PROCESS',coord:'0xFFFF · ROOT ACCESS',glyph:'✳',index:'SECTOR 06 / 08',desc:'At the center of the machine, a small sun waits for a program that does not exist yet.',tags:['ROOT','SEALED','UNEXPLORED'],neighbors:['mirror','cache','void'],pos:[76,70]},
    terminal:{name:'The Last Terminal',title:'LAST TERMINAL',type:'EXIT PROCESS',coord:'0x0000 · OUTBOUND',glyph:'↗',index:'SECTOR 07 / 08',desc:'A blinking caret points beyond the edge of the known system. A new world is only a command away.',tags:['OUTBOUND','UNKNOWN','UNEXPLORED'],neighbors:['kernel'],pos:[92,53]}
  };
  const fragments = {archive:'ECHO',relay:'PULSE',mirror:'REFLECTION',cache:'AFTERIMAGE'};
  const tips = [
    'The system keeps running while you\'re away. Idle processes slowly recover memory.',
    'Every node has a story. Use read() to inspect its contents and claim what it remembers.',
    'The network map shows only what your probes have discovered. Unknown routes are still out there.',
    'patch() trades 8 memory bytes for 30% energy. Memory is easy to find; energy is worth protecting.',
    'Your Lingua history survives a reboot. Type help() at any prompt to see the full instruction set.'
  ];
  const defaults = () => ({version:1,current:'home',discovered:['home'],visited:['home'],read:[],ciphers:[],memory:18,energy:100,complete:false,created:Date.now(),last:Date.now(),started:Date.now(),feed:[],tip:0,history:[]});
  function load(){try{const raw=JSON.parse(localStorage.getItem(SAVE_KEY));if(raw&&raw.version===1&&nodes[raw.current]){const s={...defaults(),...raw};s.discovered=s.discovered.filter(id=>nodes[id]);s.visited=s.visited.filter(id=>nodes[id]);s.read=s.read.filter(id=>nodes[id]);s.ciphers=s.ciphers.filter(x=>Object.values(fragments).includes(x));const away=Math.max(0,Date.now()-s.last);s.memory=Math.min(999,Math.floor(s.memory+away/90000));s.energy=Math.min(100,Math.floor(s.energy+away/240000));s.last=Date.now();return s}}catch(e){}return defaults()}
  let state=load(), toastTimer, historyIndex=0, soundOn=false;
  const $=id=>document.getElementById(id);
  const el={memory:$('memory'),energy:$('energy'),ciphers:$('cipher-count'),directory:$('directory'),objectiveTitle:$('objective-title'),objectiveDesc:$('objective-desc'),objectiveProgress:$('objective-progress'),objectiveCount:$('objective-count'),uptime:$('uptime'),crumb:$('crumb-node'),title:$('node-title'),type:$('node-type'),coord:$('node-coord'),index:$('node-index'),worldName:$('world-name'),worldDesc:$('world-desc'),tags:$('world-tags'),glyph:$('core-glyph'),status:$('node-status'),latency:$('latency'),event:$('world-event'),nearby:$('nearby-list'),nearbyStatus:$('nearby-status'),map:$('mini-map'),terminal:$('terminal-output'),feed:$('feed-list'),input:$('command-input'),modal:$('modal-backdrop'),toast:$('toast')};
  function save(){state.last=Date.now();try{localStorage.setItem(SAVE_KEY,JSON.stringify(state))}catch(e){}}
  function timeFmt(ms){const n=Math.max(0,Math.floor(ms/1000)),h=String(Math.floor(n/3600)).padStart(2,'0'),m=String(Math.floor(n%3600/60)).padStart(2,'0'),s=String(n%60).padStart(2,'0');return `${h}:${m}:${s}`}
  function addFeed(message){state.feed.unshift({time:Date.now(),message});state.feed=state.feed.slice(0,20)}
  function toast(text){el.toast.textContent=text;el.toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.toast.classList.remove('show'),2300)}
  function line(text,type='system-line'){const row=document.createElement('div');row.className=`terminal-line ${type}`;const prefix=document.createElement('span');prefix.className='line-prefix';prefix.textContent=type==='user-line'?'»':type==='error-line'?'!':'·';const content=document.createElement('span');content.textContent=text;row.append(prefix,content);el.terminal.append(row);el.terminal.scrollTop=el.terminal.scrollHeight;while(el.terminal.children.length>45)el.terminal.firstChild.remove()}
  function current(){return nodes[state.current]}
  function isKnown(id){return state.discovered.includes(id)}
  function connected(id){return nodes[state.current].neighbors.includes(id)}
  function cost(n){if(state.energy<n){line(`energy fault: ${n}% required, ${state.energy}% available. Use patch().`,'error-line');return false}state.energy-=n;return true}
  function revealNeighbors(){let fresh=[];current().neighbors.forEach(id=>{if(!isKnown(id)){state.discovered.push(id);fresh.push(id)}});if(fresh.length){addFeed(`New routes indexed: <b>${fresh.map(id=>nodes[id].name).join(', ')}</b>`);line(`probe complete: indexed ${fresh.length} new route${fresh.length===1?'':'s'} — ${fresh.map(id=>nodes[id].name).join(', ')}.`,'success-line');}else line('probe complete: all adjacent routes are already indexed. Nothing new in this sector.');state.memory=Math.min(999,state.memory+2);render();save()}
  function probe(){if(!cost(2))return;revealNeighbors()}
  function move(id){if(!nodes[id]){line(`route fault: '${id}' is not a valid process.`,'error-line');return}if(!isKnown(id)){line(`route fault: ${id} is not indexed. Run probe() first.`,'error-line');return}if(id===state.current){line(`already attached to ${nodes[id].name}.`);return}if(!connected(id)){line(`route fault: ${id} is outside this node's neighborhood. No physical shortcut exists.`,'error-line');return}if(!cost(4))return;state.current=id;if(!state.visited.includes(id)){state.visited.push(id);addFeed(`Operator attached to <b>${nodes[id].name}</b>`)}line(`link established → ${nodes[id].name}. Process context switched.`,'success-line');render();save();if(id==='terminal'&&!state.complete)line('outbound port detected. The system is waiting for its final instruction.');}
  function readNode(){let id=state.current;if(state.read.includes(id)){line(`read() → ${nodes[id].name} has no unread blocks. Its memory is already in your process.`);return}if(!cost(3))return;state.read.push(id);state.memory=Math.min(999,state.memory+8);if(fragments[id]){const frag=fragments[id];if(!state.ciphers.includes(frag)){state.ciphers.push(frag);line(`decrypted cipher [${frag}]. A memory shard joins your collection.`,'success-line');addFeed(`Cipher recovered: <b>${frag}</b> · ${state.ciphers.length}/4`)}else line(`cipher [${frag}] was already recovered. +8 memory bytes.`)}else line(`read complete: ${nodes[id].name} yielded 8 memory bytes. No cipher signature found.`,'success-line');render();save()}
  function patch(){if(state.energy>=100){line('patch() → energy buffer already full. No patch required.');return}if(state.memory<8){line('memory fault: patch requires 8 bytes. Read a node or wait for idle processes.','error-line');return}state.memory-=8;const before=state.energy;state.energy=Math.min(100,state.energy+30);line(`patch applied: ${before}% → ${state.energy}% energy. (−8 memory bytes)`,'success-line');addFeed('System patch applied · +30% energy');render();save()}
  function weave(){if(state.current!=='kernel'){line('weave() requires root context. Route to the Kernel of Dawn first.','error-line');return}if(state.ciphers.length<4){line(`weave fault: ${4-state.ciphers.length} cipher${state.ciphers.length===3?'':'s'} still missing. Follow the network and read() each fragment node.`,'error-line');return}if(state.complete){line('weave() already compiled. The outbound process is available at /world/terminal.');return}if(!cost(10))return;state.complete=true;state.memory+=40;addFeed('Lumen compiled · outbound process awakened');line('LINGUA: weave(ECHO, PULSE, REFLECTION, AFTERIMAGE) → LUMEN.','success-line');line('A new process wakes. Follow the outbound route to The Last Terminal.');toast('LUMEN compiled · the world has changed');render();save()}
  function execute(raw){const source=raw.trim();if(!source)return;state.history.push(source);state.history=state.history.slice(-30);historyIndex=state.history.length;line(source,'user-line');const parsed=source.toLowerCase().replace(/;$/,'').match(/^([a-z_]+)\s*(?:\(\s*(.*?)\s*\))?$/);if(!parsed){line('syntax error: expected instruction() or instruction("argument"). Try help().','error-line');return}const cmd=parsed[1],arg=(parsed[2]||'').trim().replace(/^['"]|['"]$/g,'').toLowerCase();switch(cmd){case'help':case'man':openModal('help');break;case'probe':case'scan':probe();break;case'link':case'route':case'cd':if(!arg){line('argument required: link("relay")','error-line');break}move(arg);break;case'read':case'inspect':readNode();break;case'patch':case'recharge':patch();break;case'weave':case'compile':weave();break;case'status':case'whoami':line(`PROCESS ${state.current} · ${state.energy}% energy · ${state.memory} bytes · ${state.ciphers.length}/4 ciphers · ${state.visited.length}/8 sectors visited.`);break;case'clear':el.terminal.innerHTML='';line('terminal buffer cleared. The world remembers.');break;case'reset':line('reset is available from the help panel. Local save removal requires confirmation.','error-line');break;case'exit':if(state.complete&&state.current==='terminal'){line('SYSTEM EXIT: Your program has become a world. This machine is still yours.');addFeed('Operator departed; world continues running');toast('Exit process reached · progress saved locally');}else line('exit fault: outbound process is not ready. Follow the objective first.','error-line');break;default:line(`unknown instruction '${cmd}'. Lingua is strict but friendly. Try help().`,'error-line')}}
  const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  function renderDirectory(){el.directory.innerHTML='';state.discovered.forEach(id=>{const n=nodes[id],b=document.createElement('button');b.className=`dir-entry${state.current===id?' active':''}`;b.innerHTML=`<span class="dir-glyph">${n.glyph}</span><span>${esc(id)}</span><span class="dir-state">${state.visited.includes(id)?'●':'○'}</span>`;b.title=n.name;b.onclick=()=>move(id);el.directory.append(b)});if(state.complete&&!isKnown('terminal')){const b=document.createElement('button');b.className='dir-entry';b.innerHTML='<span class="dir-glyph">↗</span><span>terminal</span><span class="dir-state">○</span>';b.onclick=()=>{state.discovered.push('terminal');render();move('terminal')};el.directory.append(b)}}
  function renderNearby(){const unknown=current().neighbors.filter(id=>isKnown(id)),notFound=current().neighbors.filter(id=>!isKnown(id));el.nearby.innerHTML='';if(!unknown.length){el.nearby.innerHTML=`<div class="empty-nearby">${notFound.length?'No routes indexed in this sector. Run <span style="color:var(--cyan)">probe()</span> to search.':'You reached the edge of the known network.'}</div>`;el.nearbyStatus=el.nearbyStatus||$('nearby-status')}unknown.forEach(id=>{const n=nodes[id],row=document.createElement('div');row.className='process-row';const reachable=connected(id);row.innerHTML=`<span class="process-symbol">${n.glyph}</span><span class="process-info"><strong>${esc(n.name)}</strong><small>${state.visited.includes(id)?'VISITED PROCESS':'ROUTE AVAILABLE'} · ${n.coord.split('·')[0]}</small></span><button class="connect-button" ${reachable?'':'disabled'}>${state.current===id?'HERE':'LINK ↗'}</button>`;const button=row.querySelector('button');button.onclick=()=>move(id);el.nearby.append(row)});$('nearby-status').textContent=unknown.length?`${unknown.length} ROUTE${unknown.length===1?'':'S'} INDEXED · ${notFound.length} UNKNOWN`:'PROBE TO INDEX ROUTES'}
  function renderMap(){const rect=el.map.getBoundingClientRect(),w=rect.width||250,h=rect.height||160;el.map.innerHTML='';const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox',`0 0 ${w} ${h}`);svg.setAttribute('preserveAspectRatio','none');svg.style.cssText='position:absolute;inset:0;width:100%;height:100%;overflow:visible';Object.entries(nodes).forEach(([id,n])=>n.neighbors.forEach(other=>{if(id>=other)return;const b=nodes[other],x1=n.pos[0]/100*w,y1=n.pos[1]/100*h,x2=b.pos[0]/100*w,y2=b.pos[1]/100*h,line=document.createElementNS('http://www.w3.org/2000/svg','line');line.setAttribute('x1',x1);line.setAttribute('y1',y1);line.setAttribute('x2',x2);line.setAttribute('y2',y2);line.setAttribute('stroke',isKnown(id)&&isKnown(other)?'#49857a':'#263635');line.setAttribute('stroke-width','1');line.setAttribute('stroke-dasharray',isKnown(id)&&isKnown(other)?'':'3 4');svg.append(line)}));el.map.append(svg);Object.entries(nodes).forEach(([id,n])=>{if(id==='terminal'&&!state.complete)return;const [x,y]=n.pos,button=document.createElement('button');button.className=`map-node ${id===state.current?'current':isKnown(id)?'discovered':'locked'}`;button.style.left=`${x}%`;button.style.top=`${y}%`;button.title=`${n.name}${isKnown(id)?'':' · not indexed'}`;button.setAttribute('aria-label',button.title);button.onclick=()=>{if(!isKnown(id)){toast('Unindexed process · use probe() from a nearby node');return}if(connected(id))move(id);else if(id===state.current)line(`current process: ${n.name}.`);else toast('No direct route · follow the network connections')};el.map.append(button);const label=document.createElement('span');label.className='map-label';label.textContent=id.toUpperCase();label.style.left=`${x}%`;label.style.top=`${y}%`;label.style.transform=`translate(${x>79?'-105%':'12px'},${y>70?'-20px':'8px'})`;el.map.append(label)})}
  function renderFeed(){el.feed.innerHTML='';if(!state.feed.length){el.feed.innerHTML='<div class="empty-nearby">The network is quiet.<br>Your actions will appear here.</div>';return}state.feed.slice(0,8).forEach(item=>{const row=document.createElement('div');row.className='feed-item';const msg=document.createElement('div');msg.className='feed-message';msg.innerHTML=item.message;const time=document.createElement('span');time.className='feed-time';time.textContent=new Date(item.time).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});row.append(time,msg);el.feed.append(row)})}
  function render(){const n=current();el.memory.textContent=String(state.memory).padStart(3,'0');el.energy.textContent=String(state.energy).padStart(3,'0');el.ciphers.textContent=`${state.ciphers.length} / 4`;el.crumb.textContent=state.current;el.title.textContent=n.title;el.type.textContent=n.type;el.coord.textContent=n.coord;el.index.textContent=n.index;el.worldName.textContent=n.name;el.worldDesc.textContent=n.desc;el.glyph.textContent=n.glyph;el.tags.innerHTML='';n.tags.forEach((tag,i)=>{const span=document.createElement('span');span.textContent=tag;if(state.read.includes(state.current)&&i===2)span.textContent='INDEXED';if(fragments[state.current]&&!state.ciphers.includes(fragments[state.current])&&i===2)span.textContent='CIPHER SIGNATURE';el.tags.append(span)});el.status.textContent=state.read.includes(state.current)?'PROCESS INDEXED':fragments[state.current]&&!state.ciphers.includes(fragments[state.current])?'CIPHER SIGNAL DETECTED':'PROCESS IDLE';el.latency.textContent=String(4+((state.current.charCodeAt(0)*7)%19)).padStart(2,'0');el.event.textContent=state.complete?'LUMEN PROCESS ACTIVE':'NO SIGNAL LOST';$('core-art').style.filter=state.current==='kernel'?'hue-rotate(35deg) brightness(1.25)':state.current==='void'?'hue-rotate(90deg) brightness(.8)':'';let count=state.ciphers.length;el.objectiveProgress.style.width=`${state.complete?100:count/4*100}%`;el.objectiveCount.textContent=state.complete?'LUMEN COMPILED':`${count} / 4 CIPHERS`;if(state.complete){el.objectiveTitle.textContent='Find the outbound process';el.objectiveDesc.textContent=state.current==='terminal'?'You reached the edge. The system keeps running.':'All ciphers woven. Reach the Kernel, then follow the new route.'}else if(count===4){el.objectiveTitle.textContent='Weave the ciphers';el.objectiveDesc.textContent='Route to Kernel of Dawn and run weave().'}else{el.objectiveTitle.textContent=count?'Gather the ciphers':'Wake the system';el.objectiveDesc.textContent=count?`${4-count} cipher${4-count===1?'':'s'} remain. Probe each route and read the nodes that hold them.`:'Probe nearby nodes. Four ciphers are scattered across the network.'}renderDirectory();renderNearby();renderMap();renderFeed();$('tip-text').textContent=tips[state.tip%tips.length];$('tip-index').textContent=String(state.tip%tips.length+1).padStart(2,'0');$('focus-action').title=state.current==='kernel'?'Weave ciphers':state.read.includes(state.current)?'Node indexed':'Read this node';$('focus-action').onclick=()=>state.current==='kernel'&&state.ciphers.length===4?execute('weave()'):execute('read()')}
  const syntax=[['probe()','Index adjacent processes. Costs 2 energy.'],['link("relay")','Move to an indexed neighboring process. Costs 4 energy.'],['read()','Read the current process. Find a cipher or recover memory.'],['patch()','Trade 8 memory bytes for up to 30% energy.'],['weave()','At Kernel of Dawn, compile the four ciphers into Lumen.'],['status() · help()','Inspect your process or open this language guide.']];
  function openModal(kind='help'){const isProfile=kind==='profile';$('modal-title').textContent=isProfile?'Operator profile.':'A language for the void.';$('modal-intro').textContent=isProfile?`OPERATOR_01 · ${state.visited.length} sectors visited · ${state.ciphers.length}/4 ciphers · ${state.memory} memory bytes. Your world lives in this browser's local save.`:'Lingua is the instruction set your machine understands. Type a command below and the world will answer.';$('syntax-list').innerHTML=syntax.map(([a,b])=>`<div class="syntax-row"><code>${a}</code><span>${b}</span></div>`).join('');$('reset-save').style.display=isProfile?'inline':'none';el.modal.classList.add('open')}
  $('command-form').addEventListener('submit',e=>{e.preventDefault();const cmd=el.input.value;el.input.value='';execute(cmd);save()});$('probe-button').onclick=()=>execute('probe()');$('clear-terminal').onclick=()=>execute('clear()');$('help-open').onclick=()=>openModal('help');$('profile-open').onclick=()=>openModal('profile');$('modal-close').onclick=()=>$('modal-backdrop').classList.remove('open');$('modal-start').onclick=()=>$('modal-backdrop').classList.remove('open');$('modal-backdrop').addEventListener('click',e=>{if(e.target===$('modal-backdrop'))$('modal-backdrop').classList.remove('open')});$('reset-save').onclick=()=>{if(confirm('Erase this browser\'s NULLSPACE save and restart from the beginning?')){localStorage.removeItem(SAVE_KEY);state=defaults();el.terminal.innerHTML='';addFeed('New process booted · operator connected');line('system boot: welcome to NULLSPACE. A persistent world is waiting beyond this prompt.');line('try probe() to index nearby nodes, then link("relay") or read().');render();save();$('modal-backdrop').classList.remove('open');toast('Local world reset')}};$('map-toggle').onclick=()=>document.querySelector('.mini-map').scrollIntoView({behavior:'smooth',block:'center'});$('map-expand').onclick=()=>openModal('help');$('next-tip').onclick=()=>{state.tip++;render();save()};$('sound-toggle').onclick=()=>{soundOn=!soundOn;$('sound-toggle').style.color=soundOn?'var(--cyan)':'';toast(soundOn?'Ambient signal enabled':'Ambient signal muted')};
  el.input.addEventListener('keydown',e=>{if(e.key==='ArrowUp'||e.key==='ArrowDown'){e.preventDefault();if(!state.history.length)return;historyIndex=Math.max(0,Math.min(state.history.length,historyIndex+(e.key==='ArrowUp'?-1:1)));el.input.value=state.history[historyIndex]||''}if(e.key==='?'&&el.input.value===''){e.preventDefault();openModal('help')}});document.addEventListener('keydown',e=>{if(e.key==='Escape')el.modal.classList.remove('open');if(e.key==='/'&&!el.modal.classList.contains('open')&&document.activeElement!==el.input){e.preventDefault();el.input.focus()}});
  function tick(){const now=Date.now();$('clock').textContent=new Date(now).toLocaleTimeString([],{hour12:false});$('uptime').textContent=timeFmt(now-state.started);if(now-state.last>60000){const oldM=state.memory,oldE=state.energy;state.memory=Math.min(999,state.memory+Math.floor((now-state.last)/90000));state.energy=Math.min(100,state.energy+Math.floor((now-state.last)/240000));state.last=now;if(oldM!==state.memory||oldE!==state.energy)render();save()}}
  if(!state.feed.length){addFeed('Operator connected to <b>The Quiet Boot</b>');addFeed('System process started · waiting for instruction')};render();line('system boot: welcome to NULLSPACE. A persistent world is waiting beyond this prompt.');line('try probe() to index nearby nodes, then link("relay") or read().');tick();setInterval(tick,1000);window.addEventListener('resize',()=>renderMap());
})();

