### Lexer

```js
function lex(src){
  const toks=[]; let i=0;
  const push=(type,value,pos)=>toks.push({type,value,pos});
  while(i<src.length){
    const c=src[i];
    if(c===' '||c==='\t'||c==='\r'||c==='\n'){i++;continue}
    if(c==='#' || (c==='/'&&src[i+1]==='/')){ while(i<src.length&&src[i]!=='\n')i++; continue }
    if(/[0-9]/.test(c)){ let s=i; while(i<src.length&&/[0-9.]/.test(src[i]))i++; push('num',parseFloat(src.slice(s,i)),s); continue }
    if(c==='"'||c==="'"){
      const q=c; i++; let out='';
      while(i<src.length&&src[i]!==q){ if(src[i]==='\\'&&i+1<src.length){ i++; out+=({n:'\n',t:'\t','\\':'\\','"':'"',"'":"'"}[src[i]]??src[i]); } else out+=src[i]; i++ }
      if(i>=src.length) throw new LinguaError('unterminated string literal');
      i++; push('str',out,i); continue;
    }
    if(/[A-Za-z_]/.test(c)){ let s=i; while(i<src.length&&/[A-Za-z0-9_]/.test(src[i]))i++; const w=src.slice(s,i); push('word',w,s); continue }
    const two=src.slice(i,i+2);
    if(['==','!=','<=','>=','&&','||'].includes(two)){ push('op',two,i); i+=2; continue }
    if('+-*/%(){}[],;=<>!'.includes(c)){ push('op',c,i); i++; continue }
    throw new LinguaError(`unexpected character '${c}'`);
  }
  push('eof','',src.length);
  return toks;
}
```

Note `/` could be division; comments `//` handled. Good.

### Parser

```js
class Parser {
  constructor(toks){this.toks=toks;this.i=0}
  peek(o=0){return this.toks[this.i+o]}
  next(){return this.toks[this.i++]}
  isOp(v){const t=this.peek();return t.type==='op'&&t.value===v}
  isWord(v){const t=this.peek();return t.type==='word'&&t.value===v}
  eatOp(v){ if(this.isOp(v)){this.i++;return true} return false }
  expectOp(v){ if(!this.isOp(v)) this.error(`expected '${v}'`); this.i++ }
  error(msg){ const t=this.peek(); throw new LinguaError(`${msg} near '${t.value||'end of input'}'`) }
  parseProgram(){
    const body=[];
    while(this.peek().type!=='eof'){ body.push(this.statement()) }
    return {type:'block',body}
  }
  block(){
    this.expectOp('{'); const body=[];
    while(!this.isOp('}')){ if(this.peek().type==='eof') this.error("missing '}'"); body.push(this.statement()) }
    this.i++; return {type:'block',body}
  }
  statement(){
    const t=this.peek();
    if(t.type==='word'){
      switch(t.value){
        case 'if': return this.ifStmt();
        case 'while': return this.whileStmt();
        case 'for': return this.forStmt();
        case 'repeat': case 'loop': return this.repeatStmt();
        case 'def': case 'fn': return this.defStmt();
        case 'return': this.i++; let value=null; if(!this.isOp(';')&&!this.isOp('}')&&this.peek().type!=='eof') value=this.expression(); this.eatOp(';'); return {type:'return',value};
        case 'break': this.i++; this.eatOp(';'); return {type:'break'};
      }
    }
    const expr=this.expression();
    if(this.isOp('=')){
      this.i++;
      const value=this.expression();
      this.eatOp(';');
      return {type:'assign',target:expr,value};
    }
    this.eatOp(';');
    return {type:'expr',expr};
  }
  ...
}
```

