cleanVars: keep JSON-safe values:
```js
  function cleanValue(v, depth = 0) {
    if (typeof v === 'number') return Number.isFinite(v) ? v : 0;
    if (typeof v === 'string' || typeof v === 'boolean') return v;
    if (Array.isArray(v) && depth < 3) return v.slice(0, 512).map(x => cleanValue(x, depth + 1));
    return null;
  }
  function cleanVars(raw) {
    const out = {};
    if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return out;
    Object.keys(raw).slice(0, 200).forEach(k => { if (/^[A-Za-z_][A-Za-z0-9_]*$/.test(k)) out[k] = cleanValue(raw[k]); });
    return out;
  }
  function cleanPrograms(raw) {
    const out = {};
    if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return out;
    Object.keys(raw).slice(0, 100).forEach(name => {
      const p = raw[name];
      if (!p || !Array.isArray(p.params) || !Array.isArray(p.body)) return;
      out[name] = { params: p.params.filter(x => typeof x === 'string').slice(0, 6), body: p.body };
    });
    return out;
  }
