class ReturnSignal { constructor(v){ this.value=v } }
class BreakSignal {}

class Interp {
  constructor(){ this.steps=0; this.limit=120000; this.depth=0; this.stack=[]; this.global=new Env(null) }
  tick(){ if(++this.steps>this.limit) throw new LinguaError('process budget exhausted — the loop was halted. Check your exit condition.') }
  run(ast){ for(const st of ast.body) this.exec(st,this.global) }
  execBlock(body,env){ for(const st of body) this.exec(st,env) }
  exec(st,env){
    this.tick();
    switch(st.type){
      case 'expr': { const v=this.eval(st.expr,env); if(v!==null && v!==undefined) out(`=> ${display(v)}`); break }
      case 'assign': { const v=this.eval(st.value,env); this.assign(st.target,v,env); break }
      case 'if': { if(truthy(this.eval(st.cond,env))) this.execBlock(st.then.body,env); else if(st.alt){ if(st.alt.type==='block') this.execBlock(st.alt.body,env); else this.exec(st.alt,env) } break }
      case 'while': { while(truthy(this.eval(st.cond,env))){ this.tick(); try{ this.execBlock(st.body.body,env) }catch(e){ if(e instanceof BreakSignal) break; throw e } } break }
      case 'for': { if(st.init) this.exec(st.init,env); while(st.cond===null||truthy(this.eval(st.cond,env))){ this.tick(); try{ this.execBlock(st.body.body,env) }catch(e){ if(e instanceof BreakSignal) break; throw e } if(st.step) this.exec(st.step,env) } break }
      case 'repeat': { const n=Math.floor(Number(this.eval(st.count,env))); if(!Number.isFinite(n)) throw new LinguaError('repeat() needs a number'); if(n>this.limit) throw new LinguaError('repeat() count is too large'); for(let i=0;i<n;i++){ this.tick(); try{ this.execBlock(st.body.body,env) }catch(e){ if(e instanceof BreakSignal) break; throw e } } break }
      case 'def': { state.programs[st.name]={params:st.params,body:st.body.body}; line(`process defined: ${st.name}(${st.params.join(', ')}) · it will persist.`,'success-line'); break }
      case 'return': throw new ReturnSignal(st.value?this.eval(st.value,env):null)
      case 'break': throw new BreakSignal()
      default: throw new LinguaError('unknown statement')
    }
  }
